def within_breaches(values, threshold, window):
    hits = []
    for end in range(len(values)):
        start = max(0, end - window + 1)
        chunk = values[start:end + 1]
        if sum(chunk) / len(chunk) > threshold:
            hits.append(end)
    return hits

