import re

def parse_criterion(text):
    m = re.match(r"^([a-z0-9.\-]+)(>=|<=|>|<|==|=)(\d+(?:\.\d+)?)(ms|s|%)?(?: for (\d+)s)?(?:, (stop|continue) as (failed|non-failed))?$", text.strip())
    if not m:
        raise ValueError("bad criterion")
    subject, cond, num, unit, tf, action, status = m.groups()
    value = float(num)
    if unit == "s":
        value *= 1000
    return {"subject": subject, "condition": cond, "threshold": value, "unit": "ms" if unit in ("ms", "s") else (unit or ""),
            "timeframe": int(tf) if tf else None, "stop": (action or "stop") == "stop", "fail": (status or "failed") == "failed"}

